function chooseRallyDir(world, id, pos, ni, def, canTraverseTile, canOpenDoors) {
  const myIdentity = ni?.identity;
  if (!myIdentity) return null;
  const searchRadius = Math.max(1, (def.packRadius ?? 8) | 0) * 2;

