    for (let i = _pending.length - 1; i >= 0; i--) {
      _pending[i].delay -= dt;
      if (_pending[i].delay <= 0) {
        _active.push(_pending[i].fx);
        _pending.splice(i, 1);
      }
    }
    // Advance active effects
    for (let i = _active.length - 1; i >= 0; i--) {
      _active[i].tick(dt);
      if (_active[i].expired) _active.splice(i, 1);
    }
  }

