      Number(e.startValue ?? 0),
      Number(e.toValue    ?? 0),
      Number(e.endValue   ?? e.startValue ?? 0),
      rampIn, hold, rampOut, elapsed
    );
    total += envelopeValue - Number(e.startValue ?? 0);
  }
  return total;
}

