      ctx.fillText("!", pos.x, y);
    }

    ctx.restore();
  }

  function drawRing(ctx, e, targetEntity, playerId) {
    const level = String(e?.aggroLevel || "");
    if (level !== "hunting" && level !== "alerted") return;
    const x = Number(e.pos?.x);
