 */
function moveToward(world, petId, targetX, targetY) {
  const pos = world.get(petId, Position);
  if (!pos) return;

  const dx = targetX - pos.x;
  const dy = targetY - pos.y;
  const ax = Math.abs(dx);
  const ay = Math.abs(dy);

  let mx = 0, my = 0;
